+const activeStatuses = new Set(["queued", "in_progress", "requires_action"]);
+
+type TemperatureUnit = "c" | "f";
+
+interface WeatherArguments {
+  location: string;
+  unit: TemperatureUnit;
+}
+
+interface WeatherResult extends WeatherArguments {
+  temperature: number;
+}
+
